package com.example.g.security;
import android.content.*;import android.util.Base64;import java.security.SecureRandom;import java.util.Arrays;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;
public final class SecurePinStore{private static final String PREF="security",SALT="pin_salt",HASH="pin_hash";private SecurePinStore(){}public static boolean hasPin(Context c){return c.getSharedPreferences(PREF,0).contains(HASH);}public static void save(Context c,char[] pin){byte[] salt=new byte[32];new SecureRandom().nextBytes(salt);byte[] hash=derive(pin,salt);c.getSharedPreferences(PREF,0).edit().putString(SALT,Base64.encodeToString(salt,Base64.NO_WRAP)).putString(HASH,Base64.encodeToString(hash,Base64.NO_WRAP)).apply();Arrays.fill(pin,'\0');}public static boolean verify(Context c,char[] pin){SharedPreferences p=c.getSharedPreferences(PREF,0);String s=p.getString(SALT,null),h=p.getString(HASH,null);if(s==null||h==null)return false;byte[] expected=Base64.decode(h,Base64.NO_WRAP),actual=derive(pin,Base64.decode(s,Base64.NO_WRAP));Arrays.fill(pin,'\0');return java.security.MessageDigest.isEqual(expected,actual);}private static byte[] derive(char[] pin,byte[] salt){try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(pin,salt,210000,256)).getEncoded();}catch(Exception e){throw new IllegalStateException(e);}}}
